// SmartForm preview renderer: GetSmartFormContent JSON -> one A4 HTML page (mm units).
// usage: node render.js <content.json> <out.html> [sampleRows=3] [defaultPara=AA]
const fs = require('fs');
const [, , inFile, outFile, rowsArg, defParaArg] = process.argv;
const j = JSON.parse(fs.readFileSync(inFile, 'utf8'));
const SAMPLE_ROWS = Number(rowsArg || 3);
const DEF_PARA = defParaArg || 'AA';

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const styleClass = (name) => String(name || '').replace(/_/g, '-');

// system symbols that have a known value on a one-page preview
const SYS = { 'SFSY-PAGE': '1', 'SFSY-FORMPAGES': '1', 'SFSY-JOBPAGES': '1' };

/** One SAPscript text line -> HTML: <XX>..</> char formats, &symbols& as placeholders. */
function inline(text) {
  let out = '';
  const re = /<([A-Z0-9]{1,2})>|<\/>|&([^&\s][^&]*?)&/g;
  let last = 0, m, open = 0;
  while ((m = re.exec(text))) {
    out += esc(text.slice(last, m.index));
    if (m[1]) { out += `<span id="${m[1]}" class="char">`; open++; }
    else if (m[0] === '</>') { if (open) { out += '</span>'; open--; } }
    else {
      const sym = m[2].replace(/\(.*\)$/, '');
      out += SYS[sym] !== undefined
        ? `<span class="sys" title="&${esc(m[2])}&">${SYS[sym]}</span>`
        : `<span class="sym" title="${esc(sym)}">&amp;${esc(sym)}&amp;</span>`;
    }
    last = re.lastIndex;
  }
  out += esc(text.slice(last));
  while (open--) out += '</span>';
  return out;
}

/** Text node lines -> paragraphs; '' / '=' continue the previous paragraph, '/' is a new line in it. */
function paragraphs(node) {
  const paras = [];
  let fmtUsed = false;
  for (const l of node.lines || []) {
    let f = l.format;
    if (f === '' || f === '=') {
      if (paras.length) { paras[paras.length - 1].html += (f === '' ? ' ' : '') + inline(l.text); continue; }
      f = '*';
    }
    if (f === '/' && paras.length) { paras[paras.length - 1].html += '<br>' + inline(l.text); continue; }
    if (f === '*' || f === '/') { f = DEF_PARA; fmtUsed = true; }
    paras.push({ fmt: f, html: inline(l.text) });
  }
  const cls = styleClass(node.style);
  return { fmtUsed, html: paras.map((p) => `<div class="${cls}"><div id="${p.fmt}" class="par">${p.html || '&nbsp;'}</div></div>`).join('') };
}
let defaultParaUsed = false;
const textHtml = (n) => { const r = paragraphs(n); if (r.fmtUsed) defaultParaUsed = true; return r.html; };

/** Template: fixed grid of lines x cells; texts sit in their (line, cell). */
function template(t) {
  const linesByName = {};
  for (const c of t.cells) (linesByName[c.line] = linesByName[c.line] || []).push(c);
  const rows = [];
  for (const tl of t.templateLines) for (let n = tl.from; n <= tl.to; n++) rows.push({ n, h: tl.heightMm, cells: (linesByName[tl.name] || []).sort((a, b) => a.column - b.column) });
  const at = {};
  for (const ch of t.children || []) if (ch.tableCell) (at[`${ch.tableCell.line}/${ch.tableCell.cell}`] = at[`${ch.tableCell.line}/${ch.tableCell.cell}`] || []).push(ch);
  let html = `<div class="tpl" data-node="${esc(t.name)}" style="width:${t.width?.mm ?? 0}mm">`;
  for (const r of rows) {
    html += `<div class="row" style="height:${r.h}mm">`;
    for (const c of r.cells) {
      const b = c.borders || {};
      const bs = ['top', 'right', 'bottom', 'left'].map((s) => (b[s] ? `border-${s}:${b[s]}mm solid #000;` : '')).join('');
      const inner = (at[`${r.n}/${c.column}`] || []).map((n) => (n.kind === 'text' ? textHtml(n) : '')).join('');
      html += `<div class="cell" style="width:${c.widthMm}mm;${c.fill ? `background:${c.fill};` : ''}${bs}">${inner}</div>`;
    }
    html += '</div>';
  }
  return html + '</div>';
}

const graphicsByKey = {};
for (const g of j.graphics || []) graphicsByKey[`${g.name}|${g.btype}`] = g;
function graphic(n) {
  const g = graphicsByKey[`${n.graphic.name}|${n.graphic.btype}`];
  if (!g || !g.file || !fs.existsSync(g.file)) return `<div class="missing">graphic ${esc(n.graphic.name)}</div>`;
  const b64 = fs.readFileSync(g.file).toString('base64');
  return `<img src="data:image/bmp;base64,${b64}" style="width:${g.widthMm}mm;height:${g.heightMm}mm" alt="${esc(g.name)}">`;
}

function nodes(list) {
  let html = '';
  for (const n of list || []) {
    if (n.kind === 'text') html += textHtml(n);
    else if (n.kind === 'template') html += template(n);
    else if (n.kind === 'graphic') html += graphic(n);
    else if (n.kind === 'loop' || n.kind === 'table') {
      const head = (n.children || []).filter((c) => c.kind === 'event' && c.attrs?.EVTYPE === 'H');
      const foot = (n.children || []).filter((c) => c.kind === 'event' && c.attrs?.EVTYPE === 'F');
      const body = (n.children || []).filter((c) => c.kind !== 'event');
      html += head.map((e) => nodes(e.children)).join('');
      for (let i = 0; i < SAMPLE_ROWS; i++) html += `<div class="sample">${nodes(body)}</div>`;
      html += foot.map((e) => nodes(e.children)).join('');
    } else if (n.children) html += nodes(n.children);
  }
  return html;
}

const page = j.pages[0];
let body = '';
for (const w of page.windows) {
  body += `<div class="win${w.type === 'MAIN' ? ' main' : ''}" data-win="${esc(w.name)}" title="${esc(w.name)} — ${esc(w.caption)}" style="left:${w.leftMm}mm;top:${w.topMm}mm;width:${w.widthMm}mm;height:${w.heightMm}mm">${nodes(w.content)}</div>`;
}

let css = (j.styles || []).map((s) => s.css).join('\n');
// a paragraph whose font is taller than its line spacing still needs room for the glyphs
css = css.replace(/font-size : (\d+)pt ;([^}]*?)line-height : ([\d.]+)mm/g, (m, pt, mid, lh) =>
  Number(pt) * 0.3528 * 1.15 > Number(lh) ? `font-size : ${pt}pt ;${mid}line-height : ${(Number(pt) * 0.3528 * 1.15).toFixed(2)}mm` : m);

const html = `<!doctype html><html><head><meta charset="utf-8"><title>${esc(j.form)} preview</title><style>
@page{size:210mm 297mm;margin:0}
html,body{margin:0;background:#fff}
.sheet{position:relative;width:210mm;height:297mm;background:#fff;overflow:hidden}
.win{position:absolute;box-sizing:border-box}
.win.guide{outline:0.2mm dashed #9bb}
.tpl{display:block}
.row{display:flex;overflow:hidden}
.cell{box-sizing:border-box;overflow:hidden;white-space:nowrap;flex:none}
.par{white-space:nowrap}
.sym{color:#1a4f9c;background:#e8f0fb}
.sys{color:#000}
.missing{font:8pt Arial;color:#b00;border:0.2mm dashed #b00;height:100%;box-sizing:border-box}
${css}
</style></head><body><div class="sheet">${body}</div></body></html>`;
fs.writeFileSync(outFile, html);
console.log(JSON.stringify({ out: outFile, bytes: html.length, defaultParaUsed, defaultParaFallback: DEF_PARA }));

