// One-shot stdio MCP client: start the vendor server, call one tool, print the result, exit.
// usage: node mcp-call.cjs <launcher.js> <tool> '<json args>'
const { spawn } = require('node:child_process');
const [launcher, tool, argsJson] = process.argv.slice(2);
const child = spawn(process.execPath, [launcher], { stdio: ['pipe', 'pipe', 'pipe'], env: process.env });
let buf = '';
let id = 0;
const pending = new Map();
const send = (method, params) => new Promise((res) => {
  const msg = { jsonrpc: '2.0', id: ++id, method, params };
  pending.set(id, res);
  child.stdin.write(JSON.stringify(msg) + '\n');
});
child.stdout.on('data', (d) => {
  buf += d;
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (!line) continue;
    try {
      const m = JSON.parse(line);
      if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
    } catch { /* not JSON-RPC */ }
  }
});
let err = '';
child.stderr.on('data', (d) => { err += d; });
const timer = setTimeout(() => { console.error('TIMEOUT\n' + err.slice(-2000)); child.kill(); process.exit(1); }, 240000);
(async () => {
  await send('initialize', { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'probe', version: '0' } });
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
  const r = await send('tools/call', { name: tool, arguments: JSON.parse(argsJson) });
  clearTimeout(timer);
  const text = r.result?.content?.map((c) => c.text).join('\n') ?? JSON.stringify(r.error ?? r);
  console.log(text);
  if (r.result?.isError || r.error) console.error('STDERR tail:\n' + err.slice(-1500));
  child.kill();
  process.exit(0);
})();

